// New renders the form for creating a new Outtake.
// This function is mapped to the path GET /outtakes/new
func (v OuttakesResource) New(c buffalo.Context) error {
	outtake := &models.Outtake{
		Date: time.Now(),
	}
	c.Set("outtake", outtake)

	// Set outtake type
	ot, err := outtakeTypes(c)
	if err != nil {
		return err
	}
	c.Set("selectOuttaketype", outtakeTypesToSelectables(ot, currentLang(c), c.Value("tx").(*pop.Connection)))

	animalYearNumber := c.Param("animal_year_number")
	if len(animalYearNumber) > 0 {
		// Get the DB connection from the context
		tx, ok := c.Value("tx").(*pop.Connection)
		if !ok {
			return fmt.Errorf("no transaction found")
		}

		animal := &models.Animal{}
		errCode := http.StatusOK

		// for message
		data := map[string]interface{}{
			"animalID": animalYearNumber,
		}

		c.Logger().Debug("animalYearNumber:", animalYearNumber)
		matches := AnimalYearNumberRegEx.FindStringSubmatch(animalYearNumber)
		if matches == nil {
			return fmt.Errorf("invalid year number: %s", animalYearNumber)
		}
		c.Logger().Debug("animalYearNumber regex matches:", matches)
		q := tx.Where("yearNumber = ?", matches[1])
		if len(matches) == 4 && len(matches[3]) == 2 {
			q = q.Where("year = ?", fmt.Sprintf("20%s", matches[3]))
		}

		err := q.Order("ID desc").Eager().First(animal)
		if err != nil {
			c.Logger().Debug("Error:", err)
			c.Flash().Add("danger", T.Translate(c, "outtake.animal.not.found", data))
			errCode = http.StatusNotFound
		}

		//c.Logger().Debugf("Loaded animal %v", animal)

		if animal.Outtake != nil {
			c.Flash().Add("danger", T.Translate(c, "outtake.animal.outtake.already.exist", data))
			errCode = http.StatusConflict
		}
		if errCode != http.StatusOK {
			return c.Render(errCode, r.HTML("/outtakes/new.plush.html"))
		}
		animal.Outtake = outtake
		c.Set("animal", animal)
	}

	return c.Render(http.StatusOK, r.HTML("/outtakes/new.plush.html"))
}

// Create adds a Outtake to the DB. This function is mapped to the
// path POST /outtakes
func (v OuttakesResource) Create(c buffalo.Context) error {
	// Allocate an empty Outtake
	outtake := &models.Outtake{}

	// Bind outtake to the html form elements
	if err := c.Bind(outtake); err != nil {
		return err
	}

	// Get the DB connection from the context
	tx, ok := c.Value("tx").(*pop.Connection)
	if !ok {
		return fmt.Errorf("no transaction found")
	}

	animalID := c.Param("animal_id")
	if len(animalID) <= 0 {
		return fmt.Errorf("Missing animal ID")
	}
	animal := &models.Animal{}
	if err := tx.Eager().Find(animal, animalID); err != nil {
		// cannot link animal
		return c.Render(http.StatusNotFound, r.HTML("/outtakes/new.plush.html"))
	}
	// Audit snapshot before mutating the animal (ring, outtake link).
	oldAnimal := *animal
	// save ring if needed
	animalRing := c.Param(("animal_ring"))
	if animalRing != animal.Ring.String {
		animal.Ring = nulls.NewString(animalRing)
		c.Logger().Debugf("Seting up ring %v", animal.Ring)
		if err := tx.Update(animal); err != nil {
			return err
		}
	}

	// Validate the data from the html form
	verrs, err := tx.ValidateAndCreate(outtake)
	if err != nil {
		return err
	}
	// Update animal if outtake is saved
	if !verrs.HasAny() {
		// Treatments scheduled after the outtake date are deleted: audit
		// them before the raw delete removes the records.
		deletedTreatments := models.Treatments{}
		if err := tx.Where("animal_id = ? and date >= ?", animalID, outtake.Date).All(&deletedTreatments); err != nil {
			return err
		}

		animal.OuttakeID = nulls.NewUUID(outtake.ID)
		animal.Outtake = outtake
		if err := tx.Update(animal); err != nil {
			return err
		}
		if err := tx.RawQuery("DELETE FROM treatments WHERE animal_id = ? and date >= ?",
			animalID,
			outtake.Date).Exec(); err != nil {
			return err
		}

		// Audit log: outtake creation + animal link/ring update (best effort)
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityOuttake, auditEntityID(outtake.ID), models.AuditActionCreate, nil, auditOuttakeProjection(*outtake))
		auditAnimalChange(c, tx, animal.ID, models.AuditEntityAnimal, auditEntityID(animal.ID), models.AuditActionUpdate, auditAnimalProjection(oldAnimal), auditAnimalProjection(*animal))
		for i := range deletedTreatments {
			auditAnimalChange(c, tx, animal.ID, models.AuditEntityTreatment, auditEntityID(deletedTreatments[i].ID), models.AuditActionDelete, auditTreatmentProjection(deletedTreatments[i]), nil)
		}

		// Publish event based on outtake type
		if err := tx.Find(&outtake.Type, outtake.TypeID); err == nil {
			animal.Outtake = outtake
			if outtake.Type.Error {
				if err := PublishAnimalDiedEvent(tx, animal, GetCurrentUser(c)); err != nil {
					c.Logger().Warnf("Failed to publish animal_died event: %v", err)
				}
			} else {
				if err := PublishAnimalReleasedEvent(tx, animal, GetCurrentUser(c)); err != nil {
					c.Logger().Warnf("Failed to publish animal_released event: %v", err)
				}
			}
		}
		// Full-state event: outtake fields + CurrentStatus are part of the
		// canonical state hash.
		publishAnimalStateEventWarn(c, tx, animal.ID)
	}

	if verrs.HasAny() {
		return responder.Wants("html", func(c buffalo.Context) error {
			// Make the errors available inside the html template
			c.Set("errors", verrs)

			// Render again the new.html template that the user can
			// correct the input.
			c.Set("outtake", outtake)

			return c.Render(http.StatusUnprocessableEntity, r.HTML("/outtakes/new.plush.html"))
		}).Wants("json", func(c buffalo.Context) error {
			return c.Render(http.StatusUnprocessableEntity, r.JSON(verrs))
		}).Wants("xml", func(c buffalo.Context) error {
			return c.Render(http.StatusUnprocessableEntity, r.XML(verrs))
		}).Respond(c)
	}

	// Annual statistics tables count outtakes: drop the per-year cache.
	InvalidateAnnualStatsCache()

	return responder.Wants("html", func(c buffalo.Context) error {
		// If there are no errors set a success message
		c.Flash().Add("success", T.Translate(c, "outtake.created.success"))

		// and redirect to the show page
		return c.Redirect(http.StatusSeeOther, "/animals/%v/#nav-outtake", animalID)
	}).Wants("json", func(c buffalo.Context) error {
		return c.Render(http.StatusCreated, r.JSON(outtake))
	}).Wants("xml", func(c buffalo.Context) error {
		return c.Render(http.StatusCreated, r.XML(outtake))
	}).Respond(c)
}

